import { ReactNode, FC } from 'react';

type InputType = 'text' | 'number' | 'password' | 'tel' | 'digit';
interface InputProps {
    /** 输入类型 */
    type?: InputType;
    /** 输入值 (受控) */
    value?: string;
    /** 默认值 (非受控) */
    defaultValue?: string;
    /** 占位文本 */
    placeholder?: string;
    /** 是否禁用 */
    disabled?: boolean;
    /** 是否只读 */
    readOnly?: boolean;
    /** 最大长度 */
    maxLength?: number;
    /** 是否显示清除按钮 */
    clearable?: boolean;
    /** 前缀内容 */
    prefix?: ReactNode;
    /** 后缀内容 */
    suffix?: ReactNode;
    /** 对齐方式 */
    align?: 'left' | 'center' | 'right';
    /** 值变化回调 */
    onChange?: (value: string) => void;
    /** 聚焦回调 */
    onFocus?: (e: any) => void;
    /** 失焦回调 */
    onBlur?: (e: any) => void;
    /** 清除回调 */
    onClear?: () => void;
    /** 自定义类名 */
    className?: string;
}

declare const Input: FC<InputProps>;

export { Input, Input as default };
export type { InputProps, InputType };
